// Included inside the existing server test module by run-rust.py; no production changes.
async fn audit_req(app: Arc<App>, method: &str, path: &str, host: Option<&str>, body: &str) -> Response {
    use axum::{body::Body, extract::connect_info::MockConnectInfo, http::Request};
    use tower::ServiceExt;
    let mut req = Request::builder().method(method).uri(path);
    if let Some(h) = host { req = req.header("host", h); }
    admin_app(app, "127.0.0.1:45629", &["Dash.Internal:45629".into()])
        .layer(MockConnectInfo(SocketAddr::from(([127,0,0,1],45000))))
        .oneshot(req.body(Body::from(body.to_string())).unwrap()).await.unwrap()
}
fn audit_done(ids: &[&str]) { for id in ids { println!("AUDIT {id} PASS"); } }
#[tokio::test]
async fn audit_admin_hosts_all_routes() {
    let a = test_app(0);
    let r = audit_req(a.clone(),"GET","/",None,"").await;
    assert_eq!(r.status(),403); assert!(body_json(r).await["error"].as_str().unwrap().contains("Host ''"));
    audit_done(&["B-010"]);
    for (id,host) in [("B-011","localhost:45629"),("B-012","127.0.0.1:45629"),("B-013","[::1]:45629"),("B-014","dAsH.iNtErNaL:45629")] {
        for path in ["/","/api/events","/api/status"] { assert_eq!(audit_req(a.clone(),"GET",path,Some(host),"").await.status(),200); }
        // Allowed authorities are tested at the specified 4029 too, in-process only.
        use axum::{body::Body,extract::connect_info::MockConnectInfo,http::Request}; use tower::ServiceExt;
        let specified=host.replace("45629","4029");
        for path in ["/","/api/events","/api/status"] {
            let r=admin_app(a.clone(),"127.0.0.1:4029",&["dash.internal:4029".into()]).layer(MockConnectInfo(SocketAddr::from(([127,0,0,1],45000)))).oneshot(Request::get(path).header("host",&specified).body(Body::empty()).unwrap()).await.unwrap(); assert_eq!(r.status(),200);
        }
        audit_done(&[id]);
    }
}
