    let r=get_quote(a.clone(),[127,0,0,1],None).await;assert_eq!(r.status(),503);let v=body_json(r).await;assert!(v["error"].as_str().unwrap().contains("audit insert denied"));assert!(v.get("product").is_none());assert_eq!(open_nonces(&a).len(),0);audit_done(&["B-026"]);
