    let r=challenge_qr(State(a),axum::extract::Path("x402z-fault".into())).await;assert_eq!(r.status(),503);assert!(body_json(r).await["error"].as_str().unwrap().contains("server database error"));audit_done(&["B-037"]);
    let a=test_app(0);let mut c=claims("x402z-large",100000);c.pay_to="x".repeat(10000);let ch=PaymentRequired{scheme:SCHEME.into(),network:Network::Testnet,pay_to:c.pay_to,amount_zat:100000,memo_nonce:c.memo_nonce.clone(),expires_at:now()+900};a.store.insert(&ch).unwrap();
