#[tokio::test]
async fn audit_direct_receipts_and_grace_boundaries() {
    let a=test_app(1);let ch=issue_challenge(&a).unwrap();let mut c=claims(&ch.memo_nonce,100000);c.mined_at=Some(now());
    assert_eq!(get_quote(a.clone(),[127,0,0,1],None).await.status(),402);
    let r=get_quote(a.clone(),[127,0,0,1],Some(&encode(&key(),&c))).await;assert_eq!(r.status(),200);assert!(settlement_of(&r).success);assert_eq!(a.store.get(&ch.memo_nonce).unwrap().unwrap().spent_txid.as_deref(),Some(c.txid.as_str()));audit_done(&["B-069"]);
    // Replay from another IP has enough budget for its rejection challenge.
    let r=get_quote(a.clone(),[127,0,0,2],Some(&encode(&key(),&c))).await;assert_eq!(r.status(),402);assert_eq!(r.headers()["x-payment-error"],"receipt already used");assert_eq!(body_json(r).await["error"],"receipt already used");assert_eq!(a.store.get(&ch.memo_nonce).unwrap().unwrap().spent_txid.as_deref(),Some(c.txid.as_str()));audit_done(&["B-071"]);
    let a=test_app(0);let r=get_quote(a.clone(),[127,0,0,1],Some("bad")).await;assert_eq!(r.status(),402);assert_eq!(r.headers()["x-payment-error"],"receipt malformed");assert_eq!(body_json(r).await["error"],"receipt malformed");assert!(a.store.conn_for_tests().query_row("SELECT count(*) FROM challenges WHERE spent_txid IS NOT NULL",[],|r|r.get::<_,u64>(0)).unwrap()==0);audit_done(&["B-070"]);
    let ch=issue_challenge(&a).unwrap();let mut c=claims(&ch.memo_nonce,100000);c.confirmations=0;let r=get_quote(a.clone(),[127,0,0,1],Some(&encode(&key(),&c))).await;assert_eq!(r.status(),402);assert_eq!(r.headers()["x-payment-error"],"payment has 0 confirmation(s), need 1; retry once it is mined");assert!(a.store.get(&ch.memo_nonce).unwrap().unwrap().spent_txid.is_none());audit_done(&["B-072"]);
    for (id,expiry_offset,mined_offset,min_conf,conf,want) in [("B-074",-2000,Some(-2001),1,1,200),("B-075",-2000,Some(-800),1,1,200),("B-077",-1190,None,0,0,200),("B-077",-1210,None,0,0,402)] {
        let mut a=test_app(0);{let cfg=&mut Arc::get_mut(&mut a).unwrap().cfg;cfg.expiry_grace_secs=1200;cfg.min_confirmations=min_conf;}
        let t=now();let expiry=(t as i64+expiry_offset) as u64;let ch=PaymentRequired{scheme:SCHEME.into(),network:Network::Testnet,pay_to:UA.into(),amount_zat:100000,memo_nonce:"x402z-grace".into(),expires_at:expiry};a.store.insert(&ch).unwrap();let mut c=claims(&ch.memo_nonce,100000);c.confirmations=conf;c.mined_at=mined_offset.map(|n|(t as i64+n)as u64);
        let r=get_quote(a,[127,0,0,1],Some(&encode(&key(),&c))).await;assert_eq!(r.status(),want,"{id}");audit_done(&[id]);
    }
}
#[tokio::test]
