#[tokio::test]
async fn audit_unavailable_unknown_and_malformed_redeem() {
    let a=test_app(0);let ch=issue_challenge(&a).unwrap();
    let r=post_redeem(a.clone(),serde_json::json!({"memoNonce":ch.memo_nonce,"txid":"ab".repeat(32)})).await;assert_eq!(r.status(),502);let v=body_json(r).await;assert_eq!(v["status"],"error");assert_eq!(v["reason"],"facilitator_error");assert!(a.store.get(&ch.memo_nonce).unwrap().unwrap().spent_txid.is_none());audit_done(&["B-084"]);
    let (a,count,_socket)=audit_counted_app(0).await;
    let r=post_redeem(a.clone(),serde_json::json!({"memoNonce":"x402z-unknown","txid":"ab".repeat(32)})).await;assert_eq!(r.status(),422);assert_eq!(body_json(r).await["reason"],"unknown_challenge");assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst),0);audit_done(&["B-083"]);
    for b in ["", "{", "{}"] {let r=audit_req(a.clone(),"POST","/api/redeem",Some("localhost:45629"),b).await;assert_eq!(r.status(),400);let v=body_json(r).await;assert_eq!(v["status"],"rejected");assert_eq!(v["reason"],"invalid_payload");assert!(v["message"].as_str().unwrap().starts_with("body must be {memoNonce, txid}:"));}audit_done(&["B-085"]);
    let before=feed(&a).len();
    for n in ["".to_string(),"x".repeat(60000)] {let r=post_redeem(a.clone(),serde_json::json!({"memoNonce":n,"txid":"ab".repeat(32)})).await;assert_eq!(r.status(),400);let v=body_json(r).await;assert_eq!(v["reason"],"invalid_payload");assert_eq!(v["message"],"memoNonce must be 1 to 64 characters of [A-Za-z0-9_-]");assert_eq!(feed(&a).len(),before);}assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst),0);audit_done(&["B-086"]);
    for t in ["", "zz", "ab"] {let r=post_redeem(a.clone(),serde_json::json!({"memoNonce":ch.memo_nonce,"txid":t})).await;assert_eq!(r.status(),400);let v=body_json(r).await;assert_eq!(v["reason"],"invalid_payload");assert_eq!(v["message"],"txid must be 64 hex characters");assert_eq!(feed(&a).len(),before);}assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst),0);audit_done(&["B-087"]);
}
