#[test]
fn audit_store_retention_and_concurrent_burn() {
    let a=test_app(0);let t=now();for (n,expiry,spent) in [("old",t-87601,false),("edge",t-87600,false),("live",t+900,false),("spent",t-90000,true)]{let ch=PaymentRequired{scheme:SCHEME.into(),network:Network::Testnet,pay_to:UA.into(),amount_zat:100000,memo_nonce:n.into(),expires_at:expiry};a.store.insert(&ch).unwrap();if spent{a.store.mark_spent(n,"ab",t).unwrap();}}
    assert_eq!(a.store.prune_unspent_expired_before(t-1200-86400).unwrap(),1);assert!(a.store.get("old").unwrap().is_none());for n in ["edge","live","spent"]{assert!(a.store.get(n).unwrap().is_some());}assert_eq!(a.store.count_open(t).unwrap(),1);audit_done(&["B-099"]);
    let ch=issue_challenge(&a).unwrap();let n=ch.memo_nonce;let mut joins=vec![];for tx in ["aa","bb"]{let a=a.clone();let n=n.clone();joins.push(std::thread::spawn(move||(tx,a.store.mark_spent(&n,tx,now()).unwrap())));}let results:Vec<_>=joins.into_iter().map(|j|j.join().unwrap()).collect();assert_eq!(results.iter().filter(|(_,ok)|*ok).count(),1);let winning=results.iter().find(|(_,ok)|*ok).unwrap().0;assert_eq!(a.store.get(&n).unwrap().unwrap().spent_txid.as_deref(),Some(winning));assert_eq!(a.store.conn_for_tests().query_row("SELECT count(*) FROM challenges WHERE nonce=?1",[n],|r|r.get::<_,u64>(0)).unwrap(),1);audit_done(&["B-102"]);
}
