#[tokio::test]
async fn audit_tab_fixture_persistence_and_replays() {
    use sha2::{Digest,Sha256};let a=app_with_stand_in().await;let (offer,nonce)=tab_offer_and_nonce(&a).await;let(pk,toks)=blind_n(&offer,3);let r=issue(&a,&nonce,TX_PAID_3X,&offer.key_id,&toks).await;assert_eq!(r.status(),200);let v=body_json(r).await;assert_eq!(v["keyId"],offer.key_id);assert_eq!(v["blindSignatures"].as_array().unwrap().len(),3);let r=axum::Json(v).into_response();let tokens=finalize(&pk,&toks,r).await;assert_eq!(a.store.conn_for_tests().query_row("SELECT count(*) FROM tab_issued WHERE nonce=?1",[&nonce],|r|r.get::<_,u64>(0)).unwrap(),1);assert_eq!(a.store.get(&nonce).unwrap().unwrap().spent_txid.as_deref(),Some(TX_PAID_3X));audit_done(&["B-130"]);
    let t=&tokens[0];let r=spend_token(&a,t).await;assert_eq!(r.status(),200);let s=settlement_of(&r);assert!(s.success);assert!(s.transaction.starts_with("tab:"));assert_eq!(s.payer,"");let v=body_json(r).await;let randomizer=b64_any(&t.randomizer).unwrap();let msg=b64_any(&t.msg).unwrap();let mut h=Sha256::new();h.update(randomizer);h.update(msg);let token=hex::encode(h.finalize());assert_eq!(v["settlement"]["tab"],true);assert_eq!(v["settlement"]["token"],token);assert_eq!(a.store.conn_for_tests().query_row("SELECT count(*) FROM tab_spent WHERE token_id=?1",[&token],|r|r.get::<_,u64>(0)).unwrap(),1);audit_done(&["B-131"]);
    let r=issue(&a,&nonce,TX_PAID_3X,&offer.key_id,&toks).await;assert_eq!(r.status(),422);let v=body_json(r).await;assert_eq!(v["reason"],"nonce_already_used");assert!(v.get("blindSignatures").is_none());audit_done(&["B-142","B-160"]);
    let r=get_quote_with(a.clone(),[127,0,0,1],&[(PAYMENT_HEADER,&x_payment_header(TX_PAID_3X,&nonce))]).await;assert_eq!(r.status(),402);assert_eq!(settlement_of(&r).error_reason.as_deref(),Some(reason::NONCE_USED));assert!(body_json(r).await.get("product").is_none());audit_done(&["B-064"]);
    let r=post_redeem(a.clone(),serde_json::json!({"memoNonce":nonce,"txid":TX_PAID_3X})).await;assert_eq!(r.status(),422);let v=body_json(r).await;assert_eq!(v["reason"],"nonce_already_used");assert!(v.get("content").is_none());audit_done(&["B-082"]);
    let (offer,nonce)=tab_offer_and_nonce(&a).await;let(pk,toks)=blind_n(&offer,2);let r=issue(&a,&nonce,TX_OK,&offer.key_id,&toks).await;assert_eq!(r.status(),422);let v=body_json(r).await;assert_eq!(v["status"],"rejected");assert_eq!(v["reason"],"invalid_payment");assert!(v["message"].as_str().unwrap().contains("underpaid for 2 tokens"));assert!(a.store.get(&nonce).unwrap().unwrap().spent_txid.is_none());assert_eq!(finalize(&pk,&toks[..1],issue(&a,&nonce,TX_OK,&offer.key_id,&toks[..1]).await).await.len(),1);audit_done(&["B-132"]);
}
