struct AuditSocket(tokio::task::JoinHandle<()>);impl Drop for AuditSocket{fn drop(&mut self){self.0.abort();}}
async fn audit_counted_app(rate:u32)->(Arc<App>,Arc<std::sync::atomic::AtomicUsize>,AuditSocket){let mut a=test_app(rate);let l=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let addr=l.local_addr().unwrap();assert!(addr.port()>4142);Arc::get_mut(&mut a).unwrap().cfg.facilitator_url=format!("http://{addr}");let n=Arc::new(std::sync::atomic::AtomicUsize::new(0));let c=n.clone();let guard=AuditSocket(tokio::spawn(async move{while let Ok((stream,_))=l.accept().await{c.fetch_add(1,std::sync::atomic::Ordering::SeqCst);drop(stream);}}));(a,n,guard)}
