async fn audit_status_sealed_ledger_errors_and_full_data(){
    let path=std::env::temp_dir().join(format!("kage-exec-dashboard-{}.sealed",std::process::id()));let key=[25;32];let value=serde_json::json!({"agents":[{"agent":"explicit-synthetic-fixture","dailyCapZat":50000,"spentTodayZat":0,"allowedHosts":["127.0.0.1"]}],"audit":[{"ts":1,"agent":"explicit-synthetic-fixture","host":"local","amountZat":100000,"decision":"denied","reason":"fixture cap exceeded"}]});let bytes=spendguard::sealed::seal(&key,spendguard::sealed::LEDGER_PURPOSE,[1;24],&serde_json::to_vec(&value).unwrap());std::fs::write(&path,&bytes).unwrap();
    let mut a=test_app(0);Arc::get_mut(&mut a).unwrap().cfg.agent_ledger=Some(path.to_str().unwrap().into());let r=audit_req(a.clone(),"GET","/api/status",Some("localhost:45629"),"").await;assert_eq!(r.status(),200);let v=body_json(r).await;assert!(v["ledger"]["error"].as_str().unwrap().starts_with("Setup required: X402Z_DEMO_AGENT_LEDGER_KEY not configured"));assert!(v["ledger"].get("data").is_none());audit_done(&["B-112"]);
    for mode in ["wrong","tampered","plaintext"]{let mut a=test_app(0);let cfg=&mut Arc::get_mut(&mut a).unwrap().cfg;cfg.agent_ledger=Some(path.to_str().unwrap().into());cfg.agent_ledger_key=Some(if mode=="wrong"{[26;32]}else{key});let mut raw=bytes.clone();if mode=="tampered"{let last=raw.len()-1;raw[last]^=1;}if mode=="plaintext"{raw=serde_json::to_vec(&value).unwrap();}std::fs::write(&path,raw).unwrap();let r=audit_req(a,"GET","/api/status",Some("localhost:45629"),"").await;assert_eq!(r.status(),200);let v=body_json(r).await;assert!(v["ledger"].get("data").is_none());let error=v["ledger"]["error"].as_str().unwrap();assert!(error.contains(if mode=="plaintext"{"not a sealed file"}else{"wrong key"}));}audit_done(&["B-114"]);
    std::fs::write(&path,&bytes).unwrap();let mut a=test_app(0);let cfg=&mut Arc::get_mut(&mut a).unwrap().cfg;cfg.agent_ledger=Some(path.to_str().unwrap().into());cfg.agent_ledger_key=Some(key);let r=audit_req(a,"GET","/api/status",Some("localhost:45629"),"").await;assert_eq!(r.status(),200);let v=body_json(r).await;assert_eq!(v["ledger"]["data"]["agents"],value["agents"]);assert_eq!(v["ledger"]["data"]["audit"],value["audit"]);assert!(!v.to_string().contains(&hex::encode(key)));std::fs::remove_file(path).unwrap();audit_done(&["B-115"]);
}
#[tokio::test]
async fn audit_tab_rate_exhaustion_has_no_facilitator_call(){let(a,count,_socket)=audit_counted_app(1).await;let(offer,nonce)=tab_offer_and_nonce(&a).await;let(_,toks)=blind_n(&offer,1);let r=issue(&a,&nonce,TX_OK,&offer.key_id,&toks).await;assert_eq!(r.status(),429);let retry=r.headers()["retry-after"].to_str().unwrap().parse::<u64>().unwrap();assert!(retry>0);assert_eq!(body_json(r).await["retryAfterSecs"],retry);assert_eq!(count.load(std::sync::atomic::Ordering::SeqCst),0);assert!(a.store.get(&nonce).unwrap().unwrap().spent_txid.is_none());audit_done(&["B-145"]);}
